    // This method securely deserializes objects by verifying a hash
    public static Object deserialize(byte[] data, byte[] expectedHash) throws IOException, ClassNotFoundException, SecurityException {
        // Compute hash of the received data
        byte[] receivedHash = computeSHA256(data);

        // Compare the received hash with the expected hash
        if (!MessageDigest.isEqual(receivedHash, expectedHash)) {
            throw new SecurityException("Data integrity check failed. Deserialization aborted.");
        }

        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return ois.readObject(); // Safe if data integrity is verified
        }
    }

    // Helper method to compute SHA-256 hash
    private static byte[] computeSHA256(byte[] data) throws IOException {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return digest.digest(data);
        } catch (Exception e) {
            throw new IOException("Failed to compute hash", e);
        }
    }

    public static void main(String[] args) {
        // Simulating receiving untrusted byte data (e.g., from user input or network)
        byte[] untrustedData = ...; // Assume this comes from an untrusted source
        byte[] expectedHash = ...;  // This should be securely transmitted or pre-shared

        try {
            Object obj = deserialize(untrustedData, expectedHash);
            System.out.println("Deserialized object: " + obj);
        } catch (Exception e) {
            System.err.println("Deserialization failed: " + e.getMessage());
        }
    }
}
